package ai.motoria.media.domain;

import ai.motoria.common.persistence.AuditableEntity;
import jakarta.persistence.Column;
import jakarta.persistence.Entity;
import jakarta.persistence.EnumType;
import jakarta.persistence.Enumerated;
import jakarta.persistence.Id;
import jakarta.persistence.Table;

import java.time.Instant;
import java.util.Objects;
import java.util.UUID;

/**
 * Uploaded file. Storage keys are generated by the server; the object is accepted only after confirmation
 * checked its size, content signature and sha256 (design D5).
 */
@Entity
@Table(name = "media_object", schema = "media")
public class MediaObject extends AuditableEntity {

    @Id
    @Column(name = "id", nullable = false)
    private UUID id;

    @Column(name = "owner_id", nullable = false)
    private UUID ownerId;

    @Enumerated(EnumType.STRING)
    @Column(name = "kind", nullable = false, length = 30)
    private MediaKind kind;

    @Column(name = "photo_slot", length = 30)
    private String photoSlot;

    @Column(name = "storage_key", nullable = false, length = 300)
    private String storageKey;

    @Column(name = "public_key", length = 300)
    private String publicKey;

    @Column(name = "content_type", nullable = false, length = 60)
    private String contentType;

    @Column(name = "declared_size", nullable = false)
    private long declaredSize;

    @Column(name = "size_bytes")
    private Long sizeBytes;

    @Column(name = "sha256", length = 64)
    private String sha256;

    @Column(name = "width")
    private Integer width;

    @Column(name = "height")
    private Integer height;

    @Column(name = "capture_metadata", length = 2000)
    private String captureMetadata;

    @Enumerated(EnumType.STRING)
    @Column(name = "visibility", nullable = false, length = 10)
    private MediaVisibility visibility;

    @Enumerated(EnumType.STRING)
    @Column(name = "status", nullable = false, length = 20)
    private MediaStatus status;

    @Column(name = "confirmed_at")
    private Instant confirmedAt;

    @Column(name = "rejection_code", length = 60)
    private String rejectionCode;

    @Column(name = "source_media_id")
    private UUID sourceMediaId;

    @Column(name = "page_number")
    private Integer pageNumber;

    protected MediaObject() {
    }

    public static MediaObject pendingUpload(UUID id, UUID ownerId, MediaKind kind, String photoSlot,
                                            String storageKey, String contentType, long declaredSize) {
        MediaObject media = new MediaObject();
        media.id = Objects.requireNonNull(id);
        media.ownerId = Objects.requireNonNull(ownerId);
        media.kind = Objects.requireNonNull(kind);
        media.photoSlot = photoSlot;
        media.storageKey = Objects.requireNonNull(storageKey);
        media.contentType = Objects.requireNonNull(contentType);
        media.declaredSize = declaredSize;
        media.visibility = MediaVisibility.PRIVATE;
        media.status = MediaStatus.PENDING_UPLOAD;
        return media;
    }

    public static MediaObject pageImage(MediaObject source, int pageNumber, String storageKey, long sizeBytes,
                                        String sha256, int width, int height, Instant now) {
        MediaObject media = new MediaObject();
        media.id = UUID.randomUUID();
        media.ownerId = source.ownerId;
        media.kind = MediaKind.REGISTRY_PAGE_IMAGE;
        media.storageKey = storageKey;
        media.contentType = "image/png";
        media.declaredSize = sizeBytes;
        media.sizeBytes = sizeBytes;
        media.sha256 = sha256;
        media.width = width;
        media.height = height;
        media.visibility = MediaVisibility.PRIVATE;
        media.status = MediaStatus.CONFIRMED;
        media.confirmedAt = now;
        media.sourceMediaId = source.id;
        media.pageNumber = pageNumber;
        return media;
    }

    public boolean isPending() {
        return status == MediaStatus.PENDING_UPLOAD;
    }

    public boolean isConfirmed() {
        return status == MediaStatus.CONFIRMED;
    }

    public void confirm(long sizeBytes, String sha256, Integer width, Integer height, String captureMetadata, Instant now) {
        if (status != MediaStatus.PENDING_UPLOAD) {
            throw new IllegalStateException("Media must be PENDING_UPLOAD but was " + status);
        }
        this.sizeBytes = sizeBytes;
        this.sha256 = sha256;
        this.width = width;
        this.height = height;
        this.captureMetadata = captureMetadata;
        this.status = MediaStatus.CONFIRMED;
        this.confirmedAt = now;
    }

    public void attachPublicCopy(String publicKey) {
        this.publicKey = Objects.requireNonNull(publicKey);
        this.visibility = MediaVisibility.PUBLIC;
    }

    public void reject(String rejectionCode) {
        this.status = MediaStatus.REJECTED;
        this.rejectionCode = rejectionCode;
    }

    public boolean isOwnedBy(UUID userId) {
        return ownerId.equals(userId);
    }

    public UUID getId() {
        return id;
    }

    public UUID getOwnerId() {
        return ownerId;
    }

    public MediaKind getKind() {
        return kind;
    }

    public String getPhotoSlot() {
        return photoSlot;
    }

    public String getStorageKey() {
        return storageKey;
    }

    public String getPublicKey() {
        return publicKey;
    }

    public String getContentType() {
        return contentType;
    }

    public long getDeclaredSize() {
        return declaredSize;
    }

    public Long getSizeBytes() {
        return sizeBytes;
    }

    public String getSha256() {
        return sha256;
    }

    public Integer getWidth() {
        return width;
    }

    public Integer getHeight() {
        return height;
    }

    public String getCaptureMetadata() {
        return captureMetadata;
    }

    public MediaVisibility getVisibility() {
        return visibility;
    }

    public MediaStatus getStatus() {
        return status;
    }

    public Instant getConfirmedAt() {
        return confirmedAt;
    }

    public String getRejectionCode() {
        return rejectionCode;
    }

    public UUID getSourceMediaId() {
        return sourceMediaId;
    }

    public Integer getPageNumber() {
        return pageNumber;
    }
}
